class AssetStore:
    def __init__(self, path: Optional[str] = None):
        default_path = Path("data") / "asset_library" / "assets.json"
        self.path = Path(path or os.getenv("PHS_ASSET_LIBRARY_DB", default_path))
        self.lock = RLock()
        self.data: Dict[str, Any] = {"assets": [], "playlists": []}
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            self._save()
            return
        try:
            self.data = json.loads(self.path.read_text(encoding="utf-8"))
            self.data.setdefault("assets", [])
            self.data.setdefault("playlists", [])
        except Exception:
            self.path.replace(self.path.with_suffix(".corrupt.json"))
            self.data = {"assets": [], "playlists": []}
            self._save()

    def _save(self) -> None:
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.data, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(self.path)

    def _find_asset_index(self, asset_id: str) -> int:
        for i, item in enumerate(self.data["assets"]):
            if item.get("id") == asset_id:
                return i
        return -1

    def _find_playlist_index(self, playlist_id: str) -> int:
        for i, item in enumerate(self.data["playlists"]):
            if item.get("id") == playlist_id:
                return i
        return -1

    def list_assets(self, asset_type: Optional[str] = None, tag: Optional[str] = None) -> List[Dict[str, Any]]:
        with self.lock:
            items = deepcopy(self.data["assets"])
        if asset_type:
            items = [x for x in items if x.get("asset_type") == asset_type]
        if tag:
            items = [x for x in items if tag in x.get("tags", [])]
        return sorted(items, key=lambda x: x.get("updated_at", ""), reverse=True)

    def get_asset(self, asset_id: str) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_asset_index(asset_id)
            if idx < 0:
                raise KeyError(asset_id)
            return deepcopy(self.data["assets"][idx])

    def create_asset(self, payload: AssetCreate) -> Dict[str, Any]:
        item = _dump(payload)
        item["id"] = uuid.uuid4().hex
        item["tags"] = sorted(set(item.get("tags", [])))
        item["created_at"] = _now()
        item["updated_at"] = item["created_at"]
        with self.lock:
            self.data["assets"].append(item)
            self._save()
            return deepcopy(item)

    def update_asset(self, asset_id: str, payload: AssetUpdate) -> Dict[str, Any]:
        patch = _dump(payload)
        with self.lock:
            idx = self._find_asset_index(asset_id)
            if idx < 0:
                raise KeyError(asset_id)
            item = self.data["assets"][idx]
            item.update(patch)
            if "tags" in patch:
                item["tags"] = sorted(set(item.get("tags", [])))
            item["updated_at"] = _now()
            self._save()
            return deepcopy(item)

    def delete_asset(self, asset_id: str) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_asset_index(asset_id)
            if idx < 0:
                raise KeyError(asset_id)
            item = self.data["assets"].pop(idx)
            for pl in self.data["playlists"]:
                pl["asset_ids"] = [x for x in pl.get("asset_ids", []) if x != asset_id]
                pl["updated_at"] = _now()
            self._save()
            return deepcopy(item)

    def asset_exists(self, asset_id: str) -> bool:
        return self._find_asset_index(asset_id) >= 0


class AssetSearch:
    sort_fields = {
        "usage": "usage_count",
        "usage_count": "usage_count",
        "rating": "rating",
        "duration": "duration_seconds",
        "duration_seconds": "duration_seconds",
        "name": "name",
        "created": "created_at",
        "updated": "updated_at",
    }

    def __init__(self, store: AssetStore):
        self.store = store

    def search(
        self,
        q: Optional[str] = None,
        tags: Optional[List[str]] = None,
        asset_type: Optional[str] = None,
        sort_by: str = "updated",
        order: str = "desc",
        limit: int = 100,
    ) -> List[Dict[str, Any]]:
        items = self.store.list_assets(asset_type=asset_type)
        if q:
            q_lower = q.lower()
            items = [x for x in items if self._match_text(x, q_lower)]
        if tags:
            required = set(tags)
            items = [x for x in items if required.issubset(set(x.get("tags", [])))]
        key = self.sort_fields.get(sort_by, "updated_at")
        reverse = order.lower() != "asc"
        items.sort(key=lambda x: self._sort_value(x, key), reverse=reverse)
        return items[: max(1, min(limit, 500))]

    @staticmethod
    def _match_text(item: Dict[str, Any], q_lower: str) -> bool:
        text = " ".join([
            str(item.get("name", "")),
            str(item.get("asset_type", "")),
            str(item.get("file_path", "")),
            str(item.get("thumbnail_path", "")),
            " ".join(item.get("tags", [])),
            json.dumps(item.get("meta", {}), ensure_ascii=False),
        ]).lower()
        return q_lower in text

    @staticmethod
    def _sort_value(item: Dict[str, Any], key: str) -> Any:
        value = item.get(key)
        if key in ("usage_count", "rating", "duration_seconds"):
            return float(value or 0)
        return value or ""


class PlaylistManager:
    def __init__(self, store: AssetStore):
        self.store = store

    @staticmethod
    def _dedupe_ids(asset_ids: List[str]) -> List[str]:
        seen, result = set(), []
        for item in asset_ids:
            if item not in seen:
                seen.add(item)
                result.append(item)
        return result

    def _valid_ids(self, asset_ids: List[str]) -> List[str]:
        return [x for x in self._dedupe_ids(asset_ids) if self.store.asset_exists(x)]

    def list(self) -> List[Dict[str, Any]]:
        with self.store.lock:
            return sorted(deepcopy(self.store.data["playlists"]), key=lambda x: x.get("updated_at", ""), reverse=True)

    def get(self, playlist_id: str) -> Dict[str, Any]:
        with self.store.lock:
            idx = self.store._find_playlist_index(playlist_id)
            if idx < 0:
                raise KeyError(playlist_id)
            item = deepcopy(self.store.data["playlists"][idx])
        item["assets"] = [self.store.get_asset(x) for x in item.get("asset_ids", []) if self.store.asset_exists(x)]
        return item

    def create(self, payload: PlaylistCreate) -> Dict[str, Any]:
        item = _dump(payload)
        item["id"] = uuid.uuid4().hex
        item["asset_ids"] = self._valid_ids(item.get("asset_ids", []))
        item["tags"] = sorted(set(item.get("tags", [])))
        item["created_at"] = _now()
        item["updated_at"] = item["created_at"]
        with self.store.lock:
            self.store.data["playlists"].append(item)
            self.store._save()
            return deepcopy(item)

    def update(self, playlist_id: str, payload: PlaylistUpdate) -> Dict[str, Any]:
        patch = _dump(payload)
        with self.store.lock:
            idx = self.store._find_playlist_index(playlist_id)
            if idx < 0:
                raise KeyError(playlist_id)
            item = self.store.data["playlists"][idx]
            item.update(patch)
            if "asset_ids" in patch:
                item["asset_ids"] = self._valid_ids(item.get("asset_ids", []))
            if "tags" in patch:
                item["tags"] = sorted(set(item.get("tags", [])))
            item["updated_at"] = _now()
            self.store._save()
            return deepcopy(item)

    def delete(self, playlist_id: str) -> Dict[str, Any]:
        with self.store.lock:
            idx = self.store._find_playlist_index(playlist_id)
            if idx < 0:
                raise KeyError(playlist_id)
            item = self.store.data["playlists"].pop(idx)
            self.store._save()
            return deepcopy(item)

    def reorder(self, playlist_id: str, asset_ids: List[str]) -> Dict[str, Any]:
        return self.update(playlist_id, PlaylistUpdate(asset_ids=self._valid_ids(asset_ids)))

    def dedupe(self, playlist_id: str) -> Dict[str, Any]:
        item = self.get(playlist_id)
        return self.reorder(playlist_id, item.get("asset_ids", []))


def create_asset_library_router(store: Optional[AssetStore] = None, prefix: str = "") -> APIRouter:
    db = store or AssetStore()
    searcher = AssetSearch(db)
    playlists = PlaylistManager(db)
    router = APIRouter(prefix=prefix, tags=["asset-library"])

    @router.get("/assets")
    def list_assets(asset_type: Optional[str] = None, tag: Optional[str] = None) -> Dict[str, Any]:
        items = db.list_assets(asset_type=asset_type, tag=tag)
        return {"items": items, "count": len(items)}

    @router.post("/assets")
    def create_asset(payload: AssetCreate) -> Dict[str, Any]:
        return db.create_asset(payload)

    @router.get("/assets/search")
    def search_assets(
        q: Optional[str] = None,
        tags: List[str] = Query(default=[]),
        asset_type: Optional[str] = None,
        sort_by: str = "updated",
        order: str = "desc",
        limit: int = Query(default=100, ge=1, le=500),
    ) -> Dict[str, Any]:
        items = searcher.search(q=q, tags=tags, asset_type=asset_type, sort_by=sort_by, order=order, limit=limit)
        return {"items": items, "count": len(items)}

    @router.get("/assets/{asset_id}")
    def get_asset(asset_id: str) -> Dict[str, Any]:
        try:
            return db.get_asset(asset_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="asset not found")

    @router.put("/assets/{asset_id}")
    def update_asset(asset_id: str, payload: AssetUpdate) -> Dict[str, Any]:
        try:
            return db.update_asset(asset_id, payload)
        except KeyError:
            raise HTTPException(status_code=404, detail="asset not found")

    @router.delete("/assets/{asset_id}")
    def delete_asset(asset_id: str) -> Dict[str, Any]:
        try:
            return {"deleted": True, "item": db.delete_asset(asset_id)}
        except KeyError:
            raise HTTPException(status_code=404, detail="asset not found")

    @router.get("/playlists")
    def list_playlists() -> Dict[str, Any]:
        items = playlists.list()
        return {"items": items, "count": len(items)}

    @router.post("/playlists")
    def create_playlist(payload: PlaylistCreate) -> Dict[str, Any]:
        return playlists.create(payload)

    @router.get("/playlists/{playlist_id}")
    def get_playlist(playlist_id: str) -> Dict[str, Any]:
        try:
            return playlists.get(playlist_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="playlist not found")

    @router.put("/playlists/{playlist_id}")
    def update_playlist(playlist_id: str, payload: PlaylistUpdate) -> Dict[str, Any]:
        try:
            return playlists.update(playlist_id, payload)
        except KeyError:
            raise HTTPException(status_code=404, detail="playlist not found")

    @router.delete("/playlists/{playlist_id}")
    def delete_playlist(playlist_id: str) -> Dict[str, Any]:
        try:
            return {"deleted": True, "item": playlists.delete(playlist_id)}
        except KeyError:
            raise HTTPException(status_code=404, detail="playlist not found")

    @router.post("/playlists/{playlist_id}/sort")
    def sort_playlist(playlist_id: str, payload: PlaylistItemsUpdate) -> Dict[str, Any]:
        try:
            return playlists.reorder(playlist_id, payload.asset_ids)
        except KeyError:
            raise HTTPException(status_code=404, detail="playlist not found")

    @router.post("/playlists/{playlist_id}/dedupe")
    def dedupe_playlist(playlist_id: str) -> Dict[str, Any]:
        try:
            return playlists.dedupe(playlist_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="playlist not found")

    return router


class AssetLibraryProvider:
    provider_id = "asset_library"
    name = "Asset Library"
    version = "0.1.0"

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.store = AssetStore(self.config.get("db_path"))
        self.search = AssetSearch(self.store)
        self.playlists = PlaylistManager(self.store)
        self.router = create_asset_library_router(self.store)

    def get_router(self) -> APIRouter:
        return self.router

    def health(self) -> Dict[str, Any]:
        return {
            "provider": self.provider_id,
            "ok": True,
            "db_path": str(self.store.path),
            "asset_count": len(self.store.data.get("assets", [])),
            "playlist_count": len(self.store.data.get("playlists", [])),
        }

    def metadata(self) -> Dict[str, Any]:
        return {
            "id": self.provider_id,
            "name": self.name,
            "version": self.version,
            "routes": ["/assets", "/assets/search", "/playlists"],
        }


def create_provider(config: Optional[Dict[str, Any]] = None) -> AssetLibraryProvider:
    return AssetLibraryProvider(config)


